  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
varying vec4 color;
  uniform vec4 viewData;
uniform sampler2D rectTexture;
#if USE_TEXTURE
  varying vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if IS_GRAY
      float gray  = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
  #endif
  o *= color;
#if USE_RECT_TEXTURE
  #if USE_PSEUDO_3D
    vec2 invGrid = 1.0 / viewData.xy;
    #define SAMPLE_AT(dx, dy) (CCSampleWithAlphaSeparated(cc_spriteTexture, uv0 + invGrid * vec2((dx), (dy))) * color)
    #define EMPTY_AT(dx, dy) (1.0 - step(0.5, SAMPLE_AT((dx), (dy)).a))
    if (o.a >= 0.5) {
      float e_T  = EMPTY_AT( 0.0,  1.0);
      float e_L  = EMPTY_AT(-1.0,  0.0);
      float e_TL = EMPTY_AT(-1.0,  1.0);
      float highlight = max(e_T * 1.3, max(e_L, e_TL));
      o.rgb *= (1.0 + highlight * viewData.w);
    } else {
      vec3 srcRgb = vec3(0.0);
      vec4 src;
      float foundShadow = 0.0;
      src = SAMPLE_AT(-1.0,  0.0); if (src.a >= 0.5) { srcRgb = src.rgb; foundShadow = 1.0; }
      if (foundShadow < 0.5) { src = SAMPLE_AT(-1.0,  1.0); if (src.a >= 0.5) { srcRgb = src.rgb; foundShadow = 1.0; } }
      if (foundShadow < 0.5) { src = SAMPLE_AT(-2.0,  0.0); if (src.a >= 0.5) { srcRgb = src.rgb; foundShadow = 1.0; } }
      if (foundShadow < 0.5) { src = SAMPLE_AT(-2.0,  1.0); if (src.a >= 0.5) { srcRgb = src.rgb; foundShadow = 1.0; } }
      if (foundShadow > 0.5) {
        o.rgb = srcRgb * (1.0 - viewData.z);
        o.a = 1.0;
      }
    }
    #undef EMPTY_AT
    #undef SAMPLE_AT
  #endif
#endif
  ALPHA_TEST(o);
#if USE_RECT_TEXTURE
  #if !USE_PSEUDO_3D
    vec4 rc = CCSampleWithAlphaSeparated(rectTexture, uv0 * viewData.xy);
    vec3 rectColor = mix(vec3(viewData.z), rc.rgb, rc.a + viewData.w);
    o.rgb *= rectColor.rgb;
  #endif
#endif
  return o;
}
void main() { gl_FragColor = frag(); }

